import { get } from './app'
import { expiryOf, settingsOf, signOf } from './garmin'
import { curveOf, readCache, slimAct, slimDay, slimNight, wallClock, weekMinutes } from './health'

// The bodies below are shaped as Garmin's Personal API reference
// (developer.garmin.com/gc-developer-program/personal/swagger-docs) documents
// them: the token endpoint answers the bare JWT, the data endpoints their DTOs.
const HOST = 'https://personal.connectapi.garmin.com'
const TOKEN_URL = `${HOST}/personalapitoken-service/personal-api/personal-api-key/token`
const KEY = 'gcpak_7f3a9c21e4b84d5f9a0c6e2b1d8f4a73'

// Saturday 28 November 2026, 10:00 in the zone the test runs in.
const NOW = new Date(2026, 10, 28, 10, 0, 0).getTime()
function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}
const b64url = (text: string) => btoa(text).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
const jwt = (exp: number) => `${b64url('{"alg":"RS256","typ":"JWT"}')}.${b64url(JSON.stringify({ sub: 'u-48151623', exp }))}.c2lnbmF0dXJl`
// A day after the tests' NOW, as the FAQ says a token lasts.
const TOKEN = jwt(Math.floor((NOW + 24 * 3600 * 1000) / 1000))

// A local wall-clock time on a day, as Garmin writes "local" timestamps: the
// local time in milliseconds as if it were UTC.
const localMs = (date: string, h: number, m: number) => {
  const [y, mo, d] = date.split('-').map(Number)
  return Date.UTC(y, mo - 1, d, h, m)
}
const DATES = ['2026-11-22', '2026-11-23', '2026-11-24', '2026-11-25', '2026-11-26', '2026-11-27', '2026-11-28']
const STEPS = [6120, 9812, 11204, 7340, 8956, 12410, 4860]
const MINUTES = [[40, 20], [10, 10], [0, 0], [25, 5], [5, 0], [0, 15], [12, 0]]

// UserDailySummaryV2DTO.
const summary = (i: number) => ({
  uuid: `5d1c8f0e-0000-4000-8000-00000000000${i}`,
  userProfilePk: 48151623,
  calendarDate: DATES[i],
  source: 'garmin',
  includesWellnessData: true,
  includesActivityData: i === 5,
  wellnessChronology: {
    startTimestampGmt: `${DATES[i]}T00:00:00.0`,
    startTimestampLocal: `${DATES[i]}T01:00:00.0`,
    endTimestampGmt: `${DATES[i]}T${i === 6 ? '08:52' : '22:59'}:00.0`,
    endTimestampLocal: `${DATES[i]}T${i === 6 ? '09:52' : '23:59'}:00.0`,
    totalDurationInMillis: 86340000,
  },
  movement: {
    steps: { goal: 8000, value: STEPS[i], distanceInMeters: Math.round(STEPS[i] * 0.76) },
    pushes: { goal: 0, value: 0, distanceInMeters: 0 },
    floorsAscended: { goal: 10, value: i === 6 ? 4 : 9, distanceInMeters: 12.2 },
    floorsDescended: { goal: 0, value: 7, distanceInMeters: 21.3 },
  },
  calories: { burnedResting: 1650, burnedActive: 420, burnedTotal: 2070, consumedGoal: 2200, consumedValue: 0, consumedRemaining: 2200 },
  heartRate: { minValue: 47, maxValue: 151, restingValue: [54, 53, 55, 54, 52, 51, 52][i], alertCount: 0 },
  intensityMinutes: { goal: 150, moderate: MINUTES[i][0], vigorous: MINUTES[i][1] },
  stress: {
    avgLevel: i === 6 ? 26 : 31, maxLevel: 92, restProportion: 0.47, activityProportion: 0.06, uncategorizedProportion: 0.03,
    lowStressProportion: 0.22, mediumStressProportion: 0.19, highStressProportion: 0.03, qualifier: 'balanced',
    totalDurationInMillis: 57600000, restDurationInMillis: 27000000, activityDurationInMillis: 3600000,
    uncategorizedDurationInMillis: 1800000, lowStressDurationInMillis: 12600000, mediumStressDurationInMillis: 10800000,
    highStressDurationInMillis: 1800000,
  },
  bodyBattery: {
    minValue: 22, maxValue: 92, chargedValue: 70, drainedValue: 18, latestValue: i === 6 ? 74 : 24, endOfDayValue: 24,
    featureVersion: '3.0',
    dynamicFeedbackEvent: { eventTimestampGmt: `${DATES[i]}T08:40:00.0`, bodyBatteryLevel: 'HIGH', feedbackShortType: 'DAY_RECOVERING_AND_INACTIVE', feedbackLongType: 'DAY_RECOVERING_AND_INACTIVE' },
    activityEvents: [],
  },
  hydration: { goalInMl: 2000, goalInFractionalMl: 2000, consumedInFractionalMl: 0 },
  respiration: { avgValue: 14, maxValue: 21, minValue: 9, latestValue: 13, latestTimestampGmt: `${DATES[i]}T08:50:00.0`, algorithmVersion: 100 },
  pulseOx: { avgValue: 95, minValue: 89, latestValue: 96, latestTimestampGmt: `${DATES[i]}T05:00:00.0`, latestTimestampLocal: `${DATES[i]}T06:00:00.0`, avgAltitudeInMeters: 31 },
})
const DAYS = DATES.map((_, i) => summary(i))

// DailySleepDTO, one a morning.
const night = (i: number, score: number, quality: string) => ({
  id: 1795800000000 + i,
  userProfilePK: 48151623,
  calendarDate: DATES[i],
  sleepTimeSeconds: 25920,
  napTimeSeconds: 0,
  sleepWindowConfirmed: true,
  sleepWindowConfirmationType: 'enhanced_confirmed_final',
  sleepStartTimestampGMT: localMs(DATES[i], 22, 12) - 24 * 3600 * 1000,
  sleepEndTimestampGMT: localMs(DATES[i], 5, 58),
  sleepStartTimestampLocal: localMs(DATES[i], 23, 12) - 24 * 3600 * 1000,
  sleepEndTimestampLocal: localMs(DATES[i], 6, 58),
  unmeasurableSleepSeconds: 0,
  deepSleepSeconds: 5220,
  lightSleepSeconds: 14400,
  remSleepSeconds: 6300,
  awakeSleepSeconds: 1200,
  deviceRemCapable: true,
  sleepFromDevice: true,
  averageSpO2Value: 94.6,
  averageRespirationValue: 13.4,
  awakeCount: 2,
  avgSleepStress: 14.2,
  ageGroup: 'ADULT',
  avgHeartRate: 53.1,
  sleepScoreFeedback: 'POSITIVE_LONG_AND_DEEP',
  sleepScoreInsight: 'NONE',
  sleepScores: {
    totalDuration: { qualifierKey: 'GOOD', optimalStart: 28800, optimalEnd: 28800 },
    stress: { qualifierKey: 'EXCELLENT', optimalStart: 0, optimalEnd: 15 },
    overall: { value: score, qualifierKey: quality },
    remPercentage: { value: 24, qualifierKey: 'EXCELLENT', optimalStart: 21, optimalEnd: 31, idealStartInSeconds: 5443, idealEndInSeconds: 8035 },
    deepPercentage: { value: 20, qualifierKey: 'GOOD', optimalStart: 16, optimalEnd: 33 },
  },
  dailyNapDTOS: [],
})
const NIGHTS = [night(0, 79, 'FAIR'), night(1, 84, 'GOOD'), night(2, 64, 'FAIR'), night(3, 86, 'GOOD'), night(4, 76, 'FAIR'), night(5, 88, 'GOOD'), night(6, 82, 'GOOD')]

// HrvSummaryDTO, one a morning.
const HRV = {
  userProfilePk: 48151623,
  hrvSummaries: DATES.map((date, i) => ({
    calendarDate: date,
    weeklyAvg: 46,
    lastNightAvg: [44, 47, 39, 50, 45, 49, 48][i],
    lastNight5MinHigh: 71,
    baseline: { lowUpper: 37, balancedLow: 41, balancedUpper: 58, markerValue: 0.39 },
    status: 'BALANCED',
    feedbackPhrase: 'HRV_BALANCED_2',
    createTimeStamp: `${date}T07:02:11.482`,
  })),
}

// Body Battery reports: a reading every 15 minutes, its columns named.
function report(date: string, from: number, until: number, level: (at: number) => number) {
  const values: any[] = []
  for (let atMs = from; atMs <= until; atMs += 15 * 60 * 1000) values.push([atMs, level(atMs), 'MEASURED', 3.0])
  return {
    date,
    charged: 70,
    drained: 18,
    startTimestampGMT: `${date}T00:00:00.0`,
    endTimestampGMT: `${date}T23:59:59.0`,
    startTimestampLocal: `${date}T00:00:00.0`,
    endTimestampLocal: `${date}T23:59:59.0`,
    bodyBatteryValuesArray: values,
    bodyBatteryValueDescriptorDTOList: [
      { bodyBatteryValueDescriptorIndex: 0, bodyBatteryValueDescriptorKey: 'timestamp' },
      { bodyBatteryValueDescriptorIndex: 1, bodyBatteryValueDescriptorKey: 'bodyBatteryLevel' },
      { bodyBatteryValueDescriptorIndex: 2, bodyBatteryValueDescriptorKey: 'bodyBatteryStatus' },
      { bodyBatteryValueDescriptorIndex: 3, bodyBatteryValueDescriptorKey: 'bodyBatteryVersion' },
    ],
    bodyBatteryActivityEvent: [],
  }
}
const MIDNIGHT = new Date(2026, 10, 28, 0, 0, 0).getTime()
const BATTERY = [
  report('2026-11-27', MIDNIGHT - 24 * 3600 * 1000, MIDNIGHT - 1, (t) => Math.max(20, 90 - Math.round((t - (MIDNIGHT - 24 * 3600 * 1000)) / 1300000))),
  report('2026-11-28', MIDNIGHT, NOW, (t) => Math.min(92, 22 + Math.round((t - MIDNIGHT) / 400000))),
]

// ActivityList entries (a few of the hundred fields each has).
const activity = (id: number, name: string, typeKey: string, start: string, distance: number, duration: number, hr: number) => ({
  activityId: id,
  activityName: name,
  description: null,
  startTimeLocal: start,
  startTimeGMT: start,
  activityType: { typeId: 1, typeKey, parentTypeId: 17 },
  eventType: { typeId: 9, typeKey: 'uncategorized' },
  distance,
  duration,
  elapsedDuration: duration + 30,
  movingDuration: duration - 20,
  elevationGain: 48,
  averageSpeed: distance / duration,
  calories: 612,
  averageHR: hr,
  maxHR: hr + 20,
  steps: 7980,
  ownerDisplayName: 'b6e1c0e2-1d2b-4c3a-9f00-6a7b8c9d0e1f',
  comments: [],
  isFavorite: false,
  isPR: false,
  hasPolyline: true,
  beginTimestamp: 1795791720000,
  sportTypeId: 1,
})
const ACTS = [
  activity(21500000005, 'Brussels Running', 'running', '2026-11-27 17:02:00', 8213.4, 2532.1, 152),
  activity(21500000004, 'Lunch Strength', 'strength_training', '2026-11-26 12:10:00', 0, 2700, 112),
  activity(21500000003, 'Evening Ride', 'road_biking', '2026-11-25 18:20:00', 32410, 4210, 138),
]
const PROFILE = {
  displayName: 'b6e1c0e2-1d2b-4c3a-9f00-6a7b8c9d0e1f',
  preferredLocale: 'en',
  measurementSystem: 'metric',
  firstDayOfWeek: { dayId: 2, dayName: 'monday', sortOrder: 2, isPossibleFirstDay: true },
  numberFormat: 'decimal_period',
  timeFormat: 'time_twenty_four_hr',
  timeZone: 'Europe/Brussels',
}

type Answer = (path: string, options: any) => any
function garmin(answers: { token?: (options: any) => any; paths?: Record<string, Answer> } = {}) {
  return mock.httpRequest((url: string, options: any) => {
    if (url === TOKEN_URL || url === TOKEN_URL.replace('.com', '.cn'))
      return answers.token ? answers.token(options) : { status: 200, headers: { 'content-type': 'text/plain' }, body: TOKEN }
    const path = url.replace(HOST, '').replace(HOST.replace('.com', '.cn'), '')
    for (const prefix of Object.keys(answers.paths || {})) if (path.startsWith(prefix)) return answers.paths![prefix](path, options)
    if (path.startsWith('/userprofile-service/userprofile/settings')) return mock.json(PROFILE)
    if (path.startsWith('/usersummary-service/v2/dailysummaries')) return mock.json({ data: DAYS })
    if (path.startsWith('/wellness-service/wellness/bodyBattery/reports/daily')) return mock.json(BATTERY)
    if (path.startsWith('/sleep-service/sleep/dailySleepSummariesByDate')) return mock.json(NIGHTS)
    if (path.startsWith('/hrv-service/hrv/daily/')) return mock.json(HRV)
    if (path.startsWith('/activitylist-service/activities/search/activities')) return mock.json(ACTS)
    return mock.response(404, { message: 'Not Found' })
  })
}
const tokenCalls = (http: any) => http.calls.filter(([url]) => url === TOKEN_URL)
const dataCalls = (http: any) => http.calls.filter(([url]) => url !== TOKEN_URL).map(([url]) => url.replace(HOST, ''))
const SIGN = signOf({ key: KEY, server: 'com' })
const withToken = (extra = {}) => ({
  apiKey: KEY,
  auth: { token: 'old.token.jwt', expires: NOW + 10 * 3600 * 1000, sign: SIGN, at: 1 },
  ...extra,
})
function textOf(node: any): string {
  if (node === null || node === undefined || node === false || node === true) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textOf).join(' ')
  return textOf(node.props?.children)
}

describe('the key', () => {
  it('shows how to make a key while there is none, and asks nothing', () => {
    const http = garmin()
    const screen = textOf(at(NOW, () => get(makeApp({ state: {} }), makeContext())))
    expect(screen).toContain('Connect Garmin')
    expect(screen).toContain('connect.garmin.com/app/settings/personalApiToken')
    expect(http.calls.length).toBe(0)
  })

  it('reads the key as pasted, with or without the header word', () => {
    expect(settingsOf(makeApp({ state: { apiKey: `  ApiKey ${KEY}\n` } })).key).toBe(KEY)
    expect(settingsOf(makeApp({ state: { apiKey: `"${KEY}"` } })).key).toBe(KEY)
    expect(settingsOf(makeApp({ state: { apiKey: KEY, server: 'cn' } })).server).toBe('cn')
  })

  it('trades the key for a token with one POST, and keeps it until it runs out', () => {
    const http = garmin()
    const app = makeApp({ state: { apiKey: KEY } })
    at(NOW, () => get(app, makeContext()))
    const [url, options] = tokenCalls(http)[0]
    expect(url).toBe(TOKEN_URL)
    expect(options.method).toBe('POST')
    expect(options.headers.Authorization).toBe(`ApiKey ${KEY}`)
    expect(app.state.auth).toMatchObject({ token: TOKEN, expires: Math.floor((NOW + 24 * 3600 * 1000) / 1000) * 1000, sign: SIGN })
    // The data calls carry the token.
    const summaries = http.calls.find(([u]) => u.includes('/v2/dailysummaries'))
    expect(summaries[1].headers.Authorization).toBe(`Bearer ${TOKEN}`)
    // Half an hour later: the same token.
    at(NOW + 30 * 60 * 1000, () => get(app, makeContext()))
    expect(tokenCalls(http).length).toBe(1)
    // An hour before it runs out: a new one.
    at(NOW + 23 * 3600 * 1000 + 60 * 1000, () => get(app, makeContext()))
    expect(tokenCalls(http).length).toBe(2)
  })

  it('reads when a token runs out from its JWT, else gives it a day', () => {
    expect(expiryOf(jwt(1795900000), NOW)).toBe(1795900000000)
    expect(expiryOf('not-a-jwt', NOW)).toBe(NOW + 24 * 3600 * 1000)
  })

  it('makes a new token for a new key', () => {
    const http = garmin()
    const app = makeApp({ state: withToken({ apiKey: 'gcpak_another_key_0000000000000000' }) })
    at(NOW, () => get(app, makeContext()))
    expect(tokenCalls(http).length).toBe(1)
    expect(tokenCalls(http)[0][1].headers.Authorization).toBe('ApiKey gcpak_another_key_0000000000000000')
  })

  it('asks the China server for an account there', () => {
    const http = garmin()
    const app = makeApp({ state: { apiKey: KEY, server: 'cn' } })
    at(NOW, () => get(app, makeContext()))
    expect(http.calls[0][0]).toBe('https://personal.connectapi.garmin.cn/personalapitoken-service/personal-api/personal-api-key/token')
    expect(http.calls.every(([url]) => url.startsWith('https://personal.connectapi.garmin.cn/'))).toBe(true)
  })

  it('says when Garmin refuses the key, and does not send it again until it changes', () => {
    const http = garmin({ token: () => mock.response(401, { message: 'Unauthorized' }) })
    const app = makeApp({ state: { apiKey: KEY } })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Garmin did not take this Personal API key')
    expect(app.state.auth.error).toContain('did not take')
    at(NOW + 3600 * 1000, () => get(app, makeContext()))
    expect(tokenCalls(http).length).toBe(1)
    // A new key is tried at once.
    app.state.apiKey = 'gcpak_new_key_000000000000000000'
    at(NOW + 3600 * 1000 + 1000, () => get(app, makeContext()))
    expect(tokenCalls(http).length).toBe(2)
  })

  it('makes a new token once when a call says 401, and asks again', () => {
    let lists = 0
    const http = garmin({
      paths: {
        '/usersummary-service/v2/dailysummaries': (path, options) => {
          lists++
          return options.headers.Authorization === 'Bearer old.token.jwt' ? mock.response(401, { message: 'Unauthorized' }) : mock.json({ data: DAYS })
        },
      },
    })
    const app = makeApp({ state: withToken() })
    at(NOW, () => get(app, makeContext()))
    expect(lists).toBe(2)
    expect(tokenCalls(http).length).toBe(1)
    expect(readCache(app)!.days.length).toBe(7)
  })
})

describe('reading', () => {
  it('reads the week, the day of Body Battery, sleep, HRV and activities, keeping only what it draws', () => {
    const http = garmin()
    const app = makeApp({ state: withToken() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(dataCalls(http)).toEqual([
      '/userprofile-service/userprofile/settings',
      '/usersummary-service/v2/dailysummaries?startDate=2026-11-22&endDate=2026-11-28',
      '/wellness-service/wellness/bodyBattery/reports/daily?startDate=2026-11-27&endDate=2026-11-28&chunks=96',
      '/sleep-service/sleep/dailySleepSummariesByDate?startDate=2026-11-22&endDate=2026-11-28',
      '/hrv-service/hrv/daily/2026-11-22/2026-11-28',
      '/activitylist-service/activities/search/activities?start=0&limit=5',
    ])
    const cache = readCache(app)!
    expect(cache.days[6]).toEqual({
      date: '2026-11-28', steps: 4860, stepGoal: 8000, meters: 3694, floors: 4, kcal: 420, rhr: 52, stress: 26,
      shares: [0.516, 0.242, 0.209, 0.033], bb: 74, bbHigh: 92, bbLow: 22, charged: 70, drained: 18, moderate: 12, vigorous: 0, imGoal: 150,
      until: '9:52',
    })
    expect(cache.nights[6]).toEqual({ date: '2026-11-28', secs: 25920, deep: 5220, light: 14400, rem: 6300, awake: 1200, score: 82, quality: 'GOOD', from: '23:12', to: '6:58' })
    expect(cache.hrv[6]).toEqual({ date: '2026-11-28', night: 48, week: 46, status: 'BALANCED', low: 41, high: 58 })
    expect(cache.acts[0]).toEqual({ id: 21500000005, name: 'Brussels Running', type: 'running', day: '2026-11-27', clock: '17:02', meters: 8213.4, secs: 2532.1, hr: 152, kcal: 612 })
    expect(cache.units).toBe('metric')
    expect(cache.weekStart).toBe('monday')
    // Nothing kept of the fields it does not draw.
    expect(JSON.stringify(cache)).not.toContain('pulseOx')
    expect(JSON.stringify(cache)).not.toContain('ownerDisplayName')
    expect(screen).toContain('Saturday 28 November')
    expect(screen).toContain('Watch data up to 9:52')
    expect(screen).toContain('74')
    expect(screen).toContain('Medium')
    expect(screen).toContain('4,860')
    expect(screen).toContain('of 8,000')
    expect(screen).toContain('82')
    expect(screen).toContain('Good')
    expect(screen).toContain('7h 12m, 23:12 - 6:58')
    expect(screen).toContain('48')
    expect(screen).toContain('Balanced')
    expect(screen).toContain('7-day average 46 ms')
    expect(screen).toContain('26')
    expect(screen).toContain('Low')
    // Monday to today: 30 + 0 + 35 + 5 + 30 + 12 (vigorous minutes count twice).
    expect(screen).toContain('112')
    expect(screen).toContain('Brussels Running')
    expect(screen).toContain('Yesterday, 8.2 km, 42:12, 152 bpm')
  })

  it('reads sleep and HRV until last night is in, then every three hours', () => {
    let nights = NIGHTS.slice(0, 6)
    const http = garmin({ paths: { '/sleep-service/sleep/dailySleepSummariesByDate': () => mock.json(nights) } })
    const app = makeApp({ state: withToken() })
    const sleepCalls = () => dataCalls(http).filter((path) => path.startsWith('/sleep-service')).length
    at(NOW, () => get(app, makeContext()))
    expect(sleepCalls()).toBe(1)
    // Half an hour later, last night still not in: again.
    at(NOW + 30 * 60 * 1000, () => get(app, makeContext()))
    expect(sleepCalls()).toBe(2)
    nights = NIGHTS
    at(NOW + 60 * 60 * 1000, () => get(app, makeContext()))
    expect(sleepCalls()).toBe(3)
    // In: not for the next three hours, the rest still every read.
    const summaries = () => dataCalls(http).filter((path) => path.startsWith('/usersummary-service')).length
    const before = summaries()
    at(NOW + 90 * 60 * 1000, () => get(app, makeContext()))
    at(NOW + 120 * 60 * 1000, () => get(app, makeContext()))
    expect(sleepCalls()).toBe(3)
    expect(summaries()).toBe(before + 2)
    at(NOW + 4 * 3600 * 1000 + 60 * 1000, () => get(app, makeContext()))
    expect(sleepCalls()).toBe(4)
    // The profile once a day.
    expect(dataCalls(http).filter((path) => path.startsWith('/userprofile-service')).length).toBe(1)
  })

  it('reads nothing before the interval, and everything at once on Try again', () => {
    const http = garmin()
    const app = makeApp({ state: withToken() })
    at(NOW, () => get(app, makeContext()))
    const calls = http.calls.length
    at(NOW + 10 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls)
    frameos.remember('force', true)
    at(NOW + 11 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBeGreaterThan(calls)
  })

  it('says a watch without HRV has none, instead of waiting for it', () => {
    garmin({ paths: { '/hrv-service/hrv/daily/': () => ({ status: 204, headers: {}, body: '' }) } })
    const app = makeApp({ state: withToken() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(readCache(app)!.hrvNone).toBe(true)
    expect(screen).toContain('No HRV from your watch')
  })

  it('uses miles and the week from Sunday when the profile says so', () => {
    garmin({ paths: { '/userprofile-service/userprofile/settings': () => mock.json({ ...PROFILE, measurementSystem: 'statute_us', firstDayOfWeek: { dayId: 1, dayName: 'sunday' } }) } })
    const app = makeApp({ state: withToken() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Yesterday, 5.1 mi, 42:12, 152 bpm')
    // Sunday the 22nd counts too: 80 more.
    expect(screen).toContain('192')
  })

  it('keeps the last read through a lost network, says so, and tries again sooner', () => {
    garmin()
    const app = makeApp({ state: withToken() })
    at(NOW, () => get(app, makeContext()))
    const sleeps = mock.setNextSleep()
    mock.httpRequest(() => ({ status: 0, error: 'Connection refused' }))
    const screen = textOf(at(NOW + 31 * 60 * 1000, () => get(app, makeContext())))
    expect(screen).toContain('Could not reach Garmin: Connection refused')
    expect(screen).toContain('4,860')
    expect(readCache(app)!.at).toBe(NOW)
    expect(sleeps.calls[sleeps.calls.length - 1][0]).toBe(60)
  })

  it('waits out a 429 for as long as Garmin asks', () => {
    garmin({ paths: { '/usersummary-service/v2/dailysummaries': () => mock.response(429, { message: 'Too Many Requests' }, { headers: { 'retry-after': '600' } }) } })
    const app = makeApp({ state: withToken() })
    const sleeps = mock.setNextSleep()
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Garmin asks the frame to slow down')
    expect(sleeps.calls[sleeps.calls.length - 1][0]).toBe(602)
    const http = garmin()
    at(NOW + 5 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(0)
  })

  it('says when nothing has synced today, and shows the last night it has', () => {
    const early = DAYS.slice(0, 6)
    garmin({
      paths: {
        '/usersummary-service/v2/dailysummaries': () => mock.json({ data: early }),
        '/sleep-service/sleep/dailySleepSummariesByDate': () => mock.json(NIGHTS.slice(0, 6)),
        '/wellness-service/wellness/bodyBattery/reports/daily': () => mock.json([]),
      },
    })
    const app = makeApp({ state: withToken() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Nothing synced from your watch today yet')
    expect(screen).toContain('Yesterday morning')
  })
})

describe('what is read', () => {
  it('reads wall-clock times as Garmin writes them', () => {
    expect(wallClock(localMs('2026-11-28', 6, 58))).toBe('6:58')
    expect(wallClock('2026-11-28T23:12:00.0')).toBe('23:12')
    expect(wallClock('2026-11-27 17:02:00')).toBe('17:02')
    expect(wallClock(null)).toBe('')
  })

  it('slims days, nights and activities that lack fields to zeros', () => {
    expect(slimDay({ calendarDate: '2026-11-28' }).steps).toBe(0)
    expect(slimNight({ calendarDate: '2026-11-28' }).score).toBe(0)
    expect(slimAct({ activityId: 1, startTimeLocal: '2026-11-27 07:30:00' })).toMatchObject({ day: '2026-11-27', clock: '7:30', meters: 0 })
  })

  it('reads the Body Battery columns by their names, one point a quarter hour, keeping the peaks', () => {
    const since = NOW - 24 * 3600 * 1000
    const curve = curveOf(BATTERY, since)
    expect(curve.length).toBeGreaterThan(90)
    expect(curve.length).toBeLessThan(100)
    expect(curve[curve.length - 1]).toEqual([Math.round(NOW / 60000), 92])
    // Columns in another order.
    const swapped = [{ ...BATTERY[1], bodyBatteryValuesArray: [[55, NOW - 60000]], bodyBatteryValueDescriptorDTOList: [
      { bodyBatteryValueDescriptorIndex: 1, bodyBatteryValueDescriptorKey: 'timestamp' },
      { bodyBatteryValueDescriptorIndex: 0, bodyBatteryValueDescriptorKey: 'bodyBatteryLevel' },
    ] }]
    expect(curveOf(swapped, since)).toEqual([[Math.round((NOW - 60000) / 60000), 55]])
    // Two readings in one quarter hour: the one further from the point before.
    const close = [{ ...BATTERY[1], bodyBatteryValuesArray: [[NOW - 3600000, 50], [NOW - 600000, 52], [NOW - 300000, 60]] }]
    expect(curveOf(close, since).map((p) => p[1])).toEqual([50, 60])
  })

  it('counts intensity minutes from the first day of the week, vigorous ones twice', () => {
    const days = DAYS.map(slimDay)
    expect(weekMinutes(days, '2026-11-28', 'monday')).toEqual({ minutes: 112, goal: 150 })
    expect(weekMinutes(days, '2026-11-28', 'saturday')).toEqual({ minutes: 12, goal: 150 })
  })
})

sources.app.tsx:
// @name Garmin
// @background #f2f4f7
// @refresh 1800
// Your day from Garmin Connect at a glance: Body Battery over the last day,
// steps against your goal, last night's sleep and its score, HRV status,
// stress, the week's steps and intensity minutes, resting heart rate and
// your last activities.
//
// It reads Garmin Connect's Personal API with a key you make on Garmin
// Connect, every half hour (the scene's refresh interval): the last seven days
// of daily summaries, the day's Body Battery and the recent activities on
// every read, sleep and HRV until last night is in and then every three
// hours, the profile's units once a day. The last read is kept on the frame's
// disk and stays up through a lost network.
//
// garmin.ts has the key and the calls, health.ts what is kept and the words,
// ui.tsx the looks and the setup screens.
import { keyPageOf, newRender, readAuth, session, settingsOf, signOf, slowDown, waitUntil } from './garmin'
import type { Settings } from './garmin'
import {
  HRV_WORDS, addDays, batteryWord, dayOf, distanceText, grouped, hours, kindOf, letterOf, longDate, readCache, refresh, sleepWord,
  stopwatch, stressWord, weekMinutes, whenText,
} from './health'
import type { Act, Cache, Day, Hrv, Night } from './health'
import { Banner, BigButton, Icon, SetupScreen, clamp, sizesOf, themeOf } from './ui'
import type { Sizes, Theme } from './ui'

const readAgain = () => frameos.remember('force', true)

// ---------------------------------------------------------------- what a render shows

type View = {
  t: Theme; z: Sizes; W: number; H: number; now: number; cache: Cache; problem: string; units: string; today: string
  day: Day; synced: boolean; days: Day[]; night: Night | null; hrv: Hrv | null; hrvNone: boolean
  battery: number; im: { minutes: number; goal: number }; rhrWeek: number; acts: Act[]
}

const BLANK = (date: string): Day => ({
  date, steps: 0, stepGoal: 0, meters: 0, floors: 0, kcal: 0, rhr: 0, stress: 0, shares: [], bb: 0, bbHigh: 0, bbLow: 0, charged: 0,
  drained: 0, moderate: 0, vigorous: 0, imGoal: 0, until: '',
})

const clockOf = (at: number) => {
  const d = new Date(at)
  return `${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`
}
const percent = (share: number) => `${Math.round(clamp(share, 0, 1) * 1000) / 10}%`
const hrvColor = (t: Theme, status: string) => (status === 'BALANCED' ? t.good : status === 'POOR' ? t.bad : status === 'NONE' || status === 'INVALID' ? t.ink : t.warn)

// ---------------------------------------------------------------- parts

function Header({ v, compact }: { v: View; compact?: boolean }) {
  const { t, z, day, synced, cache } = v
  return (
    <div className={`flex items-center gap-[${z.s(12)}px]`}>
      <div className={`w-[${z.s(compact ? 32 : 40)}px] h-[${z.s(compact ? 32 : 40)}px] shrink-0 rounded-full flex items-center justify-center ${t.badge}`}>
        <Icon name="watch" size={z.s(compact ? 18 : 22)} />
      </div>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${z.s(compact ? 17 : 21)}px] font-bold leading-tight truncate`}>{longDate(v.today)}</span>
        <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>
          {synced ? (day.until ? `Watch data up to ${day.until}` : `Read at ${clockOf(cache.at)}`) : 'Nothing synced from your watch today yet'}
        </span>
      </div>
      <div className={`w-[${z.s(40)}px] h-[${z.s(40)}px] shrink-0 rounded-full flex items-center justify-center ${t.button}`} onClick={readAgain}>
        <Icon name="refresh" size={z.s(20)} />
      </div>
    </div>
  )
}

function Label({ v, icon, color, text, right }: { v: View; icon: string; color: string; text: string; right?: string }) {
  const { t, z } = v
  return (
    <div className={`flex items-center gap-[${z.s(6)}px] min-w-0`}>
      <Icon name={icon} size={z.s(16)} color={color} />
      <span className={`flex-1 min-w-0 text-[${z.s(13)}px] font-bold ${t.muted} truncate`}>{text}</span>
      {right ? <span className={`text-[${z.s(12)}px] ${t.muted}`}>{right}</span> : null}
    </div>
  )
}

function Big({ v, value, unit, word, color, size }: { v: View; value: string; unit?: string; word?: string; color?: string; size: number }) {
  const { z } = v
  return (
    <div className={`flex items-end gap-[${z.s(6)}px] min-w-0`}>
      <span className={`text-[${z.s(size)}px] font-bold leading-none`}>{value}</span>
      {unit ? <span className={`text-[${z.s(size * 0.42)}px] pb-[${z.s(size * 0.05)}px] ${v.t.muted}`}>{unit}</span> : null}
      {word ? (
        <span className={`text-[${z.s(Math.max(13, size * 0.36))}px] font-bold pb-[${z.s(size * 0.05)}px] truncate text-[${color || v.t.ink}]`}>{word}</span>
      ) : null}
    </div>
  )
}

function Bar({ v, share, color }: { v: View; share: number; color: string }) {
  const { t, z } = v
  return (
    <div className={`h-[${z.s(8)}px] rounded-full ${t.track}`}>
      <div className={`h-full w-[${percent(share)}] min-w-[${z.s(8)}px] rounded-full bg-[${color}]`} />
    </div>
  )
}

// Body Battery over the last 24 hours, with the hours under it. A gap of an
// hour or more (the watch off the wrist) breaks the line.
function Curve({ v, width, height }: { v: View; width: number; height: number }) {
  const { t, z, now, cache } = v
  const end = Math.round(now / 60000)
  const start = end - 24 * 60
  const x = (minute: number) => Math.round(((minute - start) / (end - start)) * (width - 4) * 10) / 10 + 2
  const y = (level: number) => Math.round((1 - level / 100) * (height - 4) * 10) / 10 + 2
  const segments: number[][][] = []
  for (const point of cache.curve.filter((p) => p[0] >= start && p[0] <= end)) {
    const current = segments[segments.length - 1]
    if (!current || point[0] - current[current.length - 1][0] > 60) segments.push([point])
    else current.push(point)
  }
  const line = segments.map((seg) => seg.map((p, i) => `${i ? 'L' : 'M'}${x(p[0])} ${y(p[1])}`).join(' ')).join(' ')
  const area = segments
    .filter((seg) => seg.length > 1)
    .map((seg) => `M${x(seg[0][0])} ${height} ${seg.map((p) => `L${x(p[0])} ${y(p[1])}`).join(' ')} L${x(seg[seg.length - 1][0])} ${height} Z`)
    .join(' ')
  const ticks: { at: number; text: string }[] = []
  const first = new Date(start * 60000)
  first.setMinutes(0, 0, 0)
  for (let at = first.getTime() + 3600000; at < end * 60000 - 2 * 3600000; at += 3600000) {
    const h = new Date(at).getHours()
    if (h % 6 === 0) ticks.push({ at: Math.round(at / 60000), text: `${h}:00` })
  }
  const labelW = z.s(44)
  return (
    <div className={`flex flex-col gap-[${z.s(2)}px]`}>
      <svg className={`w-[${width}px] h-[${height}px]`} viewBox={`0 0 ${width} ${height}`} fill="none">
        {[25, 50, 75].map((level) => (
          <path d={`M0 ${y(level)} H${width}`} stroke={t.grid} strokeWidth={1} strokeDasharray={t.high ? '2 6' : undefined} />
        ))}
        {ticks.map((tick) => (
          <path d={`M${x(tick.at)} 0 V${height}`} stroke={t.grid} strokeWidth={1} strokeDasharray={t.high ? '2 6' : undefined} />
        ))}
        {area && !t.high ? <path d={area} fill={t.bbSoft} /> : null}
        {line ? <path d={line} stroke={t.bb} strokeWidth={t.high ? 3 : 2.5} strokeLinejoin="round" strokeLinecap="round" /> : null}
      </svg>
      <div className={`relative h-[${z.s(15)}px]`}>
        {ticks.map((tick) => (
          <div className={`absolute top-0 left-[${Math.round(clamp(x(tick.at) - labelW / 2, 0, width - labelW))}px] w-[${labelW}px] flex justify-center`}>
            <span className={`text-[${z.s(11)}px] ${t.muted}`}>{tick.text}</span>
          </div>
        ))}
        <div className="absolute top-0 right-0">
          <span className={`text-[${z.s(11)}px] font-bold`}>Now</span>
        </div>
      </div>
    </div>
  )
}

function BatteryCard({ v, width, chart, grow, side }: { v: View; width: number; chart: number; grow?: boolean; side?: boolean }) {
  const { t, z, day, battery } = v
  const padding = z.s(14)
  const charged = day.charged || day.drained ? `+${day.charged} charged, -${day.drained} drained today` : 'Charges while you rest and sleep'
  // Beside: the number and the words on the left, the curve on the right, for
  // an upright panel with no height to spare.
  if (side) {
    const left = Math.round((width - 2 * padding) * 0.34)
    return (
      <div className={`flex gap-[${z.s(12)}px] rounded-[${z.s(16)}px] p-[${padding}px] ${t.card}`}>
        <div className={`w-[${left}px] shrink-0 flex flex-col gap-[${z.s(6)}px]`}>
          <Label v={v} icon="bolt" color={t.bb} text="Body Battery" />
          <span className={`text-[${z.s(52)}px] font-bold leading-none`}>{battery ? String(battery) : '-'}</span>
          {battery ? <span className={`text-[${z.s(16)}px] font-bold text-[${t.bb}]`}>{batteryWord(battery)}</span> : null}
          <span className={`text-[${z.s(12)}px] ${t.muted}`}>{charged}</span>
        </div>
        {v.cache.curve.length > 1 ? <Curve v={v} width={width - 2 * padding - left - z.s(12)} height={chart} /> : null}
      </div>
    )
  }
  return (
    <div className={`${grow ? 'flex-1 min-h-0 ' : ''}flex flex-col justify-between gap-[${z.s(8)}px] rounded-[${z.s(16)}px] p-[${padding}px] ${t.card}`}>
      <Label v={v} icon="bolt" color={t.bb} text="Body Battery" />
      <Big v={v} value={battery ? String(battery) : '-'} word={battery ? batteryWord(battery) : ''} color={t.bb} size={52} />
      {chart > z.s(24) && v.cache.curve.length > 1 ? <Curve v={v} width={width - 2 * padding} height={chart} /> : null}
      <span className={`text-[${z.s(13)}px] ${t.muted} truncate`}>{charged}</span>
    </div>
  )
}

function Tile({ v, children }: { v: View; children: any }) {
  const { t, z } = v
  return (
    <div className={`flex-1 min-w-0 min-h-0 flex flex-col justify-between gap-[${z.s(6)}px] rounded-[${z.s(16)}px] p-[${z.s(12)}px] ${t.card}`}>
      {children}
    </div>
  )
}

function StepsTile({ v }: { v: View }) {
  const { t, z, day, units } = v
  const goal = day.stepGoal
  const extra = [day.meters ? distanceText(day.meters, units) : '', day.floors ? `${Math.round(day.floors)} floors` : ''].filter(Boolean).join(', ')
  return (
    <Tile v={v}>
      <Label v={v} icon="steps" color={t.steps} text="Steps" right={goal ? `of ${grouped(goal)}` : ''} />
      <Big v={v} value={grouped(day.steps)} size={34} word={goal && day.steps >= goal ? 'Goal' : ''} color={t.steps} />
      {goal ? <Bar v={v} share={day.steps / goal} color={t.steps} /> : null}
      <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{extra || 'No steps yet today'}</span>
    </Tile>
  )
}

// Last night's stages as one bar: deep, light, REM, awake. On a panel with no
// color the stages are told apart by height: deep full, REM half, light and
// awake empty.
function Stages({ v, night }: { v: View; night: Night }) {
  const { t, z } = v
  const total = night.deep + night.light + night.rem + night.awake
  if (!total) return null
  const parts = [
    { secs: night.deep, color: t.deep, h: '100%' },
    { secs: night.light, color: t.light, h: '100%' },
    { secs: night.rem, color: t.rem, h: '50%' },
    { secs: night.awake, color: t.awake, h: '100%' },
  ].filter((part) => part.secs > 0)
  return (
    <div className={`flex items-end h-[${z.s(10)}px] rounded-[${z.s(3)}px] overflow-hidden ${t.high ? 'border-2 border-black' : ''}`}>
      {parts.map((part) => (
        <div className={`w-[${percent(part.secs / total)}] h-[${t.high ? part.h : '100%'}] bg-[${part.color}]`} />
      ))}
    </div>
  )
}

function SleepTile({ v }: { v: View }) {
  const { t, z, night, today } = v
  if (!night)
    return (
      <Tile v={v}>
        <Label v={v} icon="moon" color={t.sleep} text="Sleep" />
        <span className={`text-[${z.s(14)}px] ${t.muted}`}>Last night is not in yet. It comes with the morning's sync.</span>
      </Tile>
    )
  const when = night.date === today ? (night.from && night.to ? `${night.from} - ${night.to}` : 'Last night') : `${whenText(night.date, today)} morning`
  return (
    <Tile v={v}>
      <Label v={v} icon="moon" color={t.sleep} text="Sleep" right={night.score ? 'score' : ''} />
      {night.score ? (
        <Big v={v} value={String(night.score)} word={sleepWord(night.quality)} color={t.sleep} size={34} />
      ) : (
        <Big v={v} value={hours(night.secs)} size={30} />
      )}
      <Stages v={v} night={night} />
      <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{night.score ? `${hours(night.secs)}, ${when}` : when}</span>
    </Tile>
  )
}

// The week's HRV against the person's balanced range: the range a band on the
// track, the week's average a mark above it.
function HrvBand({ v, hrv, width }: { v: View; hrv: Hrv; width: number }) {
  const { t, z } = v
  if (!hrv.low || !hrv.high || !hrv.week) return null
  const lo = Math.min(hrv.low, hrv.week) * 0.8
  const hi = Math.max(hrv.high, hrv.week) * 1.2
  const x = (value: number) => Math.round(((value - lo) / (hi - lo)) * (width - 8)) + 4
  const h = z.s(16)
  const bar = z.s(6)
  const mark = x(hrv.week)
  return (
    <svg className={`w-[${width}px] h-[${h}px]`} viewBox={`0 0 ${width} ${h}`}>
      <rect x={2} y={h - bar - 1} width={width - 4} height={bar} rx={bar / 2} fill={t.high ? '#ffffff' : t.grid} stroke={t.high ? '#000000' : 'none'} strokeWidth={1.5} />
      <rect x={x(hrv.low)} y={h - bar - 1} width={Math.max(2, x(hrv.high) - x(hrv.low))} height={bar} fill={t.good} />
      <path d={`M${mark - z.s(5)} 0 L${mark + z.s(5)} 0 L${mark} ${h - bar - 2} Z`} fill={t.ink} />
    </svg>
  )
}

function HrvTile({ v, width }: { v: View; width: number }) {
  const { t, z, hrv, hrvNone, today } = v
  if (!hrv || (!hrv.night && !hrv.week))
    return (
      <Tile v={v}>
        <Label v={v} icon="pulse" color={t.good} text="HRV status" />
        <span className={`text-[${z.s(14)}px] ${t.muted}`}>
          {hrvNone ? 'No HRV from your watch: it does not measure it, or was not worn at night.' : 'Last night is not in yet.'}
        </span>
      </Tile>
    )
  const lastNight = hrv.date === today && hrv.night
  return (
    <Tile v={v}>
      <Label v={v} icon="pulse" color={t.good} text="HRV status" right={lastNight ? 'last night' : ''} />
      <Big v={v} value={String(lastNight ? hrv.night : hrv.week)} unit="ms" word={HRV_WORDS[hrv.status] || ''} color={hrvColor(t, hrv.status)} size={34} />
      <HrvBand v={v} hrv={hrv} width={width} />
      <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{`7-day average ${hrv.week} ms`}</span>
    </Tile>
  )
}

function StressTile({ v }: { v: View }) {
  const { t, z, day } = v
  const [rest, low, medium, high] = day.shares.length === 4 ? day.shares : [0, 0, 0, 0]
  const parts = t.high
    ? [{ share: low + medium + high, color: '#000000' }]
    : [
        { share: rest, color: t.rest },
        { share: low, color: t.low },
        { share: medium, color: t.medium },
        { share: high, color: t.highStress },
      ]
  return (
    <Tile v={v}>
      <Label v={v} icon="gauge" color={t.medium} text="Stress" right={day.stress ? 'average' : ''} />
      <Big v={v} value={day.stress ? String(day.stress) : '-'} word={day.stress ? stressWord(day.stress) : ''} color={t.ink} size={34} />
      {rest + low + medium + high > 0 ? (
        <div className={`flex h-[${z.s(8)}px] rounded-full overflow-hidden ${t.track}`}>
          {parts.map((part) => <div className={`h-full w-[${percent(part.share)}] bg-[${part.color}]`} />)}
        </div>
      ) : null}
      <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{rest ? `${Math.round(rest * 100)}% of the day at rest` : 'No stress readings yet today'}</span>
    </Tile>
  )
}

// The last seven days of steps, today last and lit, the goal as a line.
function WeekSteps({ v, height }: { v: View; height: number }) {
  const { t, z, days, today } = v
  const goal = v.day.stepGoal || Math.max(...days.map((day) => day.stepGoal))
  const most = Math.max(goal, ...days.map((day) => day.steps)) || 1
  const total = days.reduce((sum, day) => sum + day.steps, 0)
  const h = Math.max(z.s(20), height)
  return (
    <div className={`flex flex-col gap-[${z.s(4)}px]`}>
      <Label v={v} icon="steps" color={t.steps} text="The last 7 days" right={`${grouped(total)} steps`} />
      <div className={`relative h-[${h}px]`}>
        <div className={`flex items-end h-full gap-[${z.s(6)}px]`}>
          {days.map((day) => (
            <div className={`flex-1 h-[${Math.max(z.s(3), Math.round((day.steps / most) * h))}px] rounded-t-[${z.s(3)}px] ${
              day.date === today ? `bg-[${t.steps}]` : t.high ? 'bg-white border-2 border-black' : `bg-[${t.stepsSoft}]`
            }`} />
          ))}
        </div>
        {goal ? <div className={`absolute left-0 right-0 top-[${h - Math.round((goal / most) * h)}px] border-t-2 border-[${t.ink}]`} /> : null}
      </div>
      <div className={`flex gap-[${z.s(6)}px]`}>
        {days.map((day) => (
          <span className={`flex-1 text-center text-[${z.s(11)}px] ${day.date === today ? 'font-bold' : t.muted}`}>{letterOf(day.date)}</span>
        ))}
      </div>
    </div>
  )
}

function Minutes({ v }: { v: View }) {
  const { t, z, im } = v
  return (
    <div className={`flex-1 min-w-0 flex flex-col gap-[${z.s(4)}px]`}>
      <Label v={v} icon="flame" color={t.im} text="Intensity minutes" />
      <div className={`flex items-end gap-[${z.s(4)}px]`}>
        <span className={`text-[${z.s(24)}px] font-bold leading-none`}>{grouped(im.minutes)}</span>
        <span className={`text-[${z.s(13)}px] ${t.muted}`}>{`of ${grouped(im.goal)} this week`}</span>
      </div>
      <Bar v={v} share={im.minutes / (im.goal || 150)} color={t.im} />
    </div>
  )
}

function Resting({ v }: { v: View }) {
  const { t, z, day, rhrWeek } = v
  return (
    <div className={`flex-1 min-w-0 flex flex-col gap-[${z.s(4)}px]`}>
      <Label v={v} icon="heart" color={t.heart} text="Resting heart rate" />
      <div className={`flex items-end gap-[${z.s(4)}px]`}>
        <span className={`text-[${z.s(24)}px] font-bold leading-none`}>{day.rhr ? String(day.rhr) : '-'}</span>
        <span className={`text-[${z.s(13)}px] ${t.muted}`}>bpm</span>
      </div>
      <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{rhrWeek ? `7-day average ${rhrWeek}` : ' '}</span>
    </div>
  )
}

function ActLine({ v, act }: { v: View; act: Act }) {
  const { units } = v
  return [whenText(act.day, v.today), act.meters >= 100 ? distanceText(act.meters, units) : '', act.secs ? stopwatch(act.secs) : '', act.hr ? `${act.hr} bpm` : '']
    .filter(Boolean)
    .join(', ')
}

function LastActivity({ v }: { v: View }) {
  const { t, z } = v
  const act = v.acts[0]
  return (
    <div className={`flex-1 min-w-0 flex flex-col gap-[${z.s(4)}px]`}>
      <Label v={v} icon={act ? kindOf(act.type) : 'run'} color={t.ink} text="Last activity" />
      {act ? (
        <div className="flex flex-col min-w-0">
          <span className={`text-[${z.s(16)}px] font-bold truncate`}>{act.name || 'Activity'}</span>
          <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{ActLine({ v, act })}</span>
        </div>
      ) : (
        <span className={`text-[${z.s(13)}px] ${t.muted}`}>None recorded yet</span>
      )}
    </div>
  )
}

// The last activity alone, one row: an upright panel with no room for the list.
function LastRow({ v }: { v: View }) {
  const { t, z } = v
  const act = v.acts[0]
  if (!act) return null
  return (
    <div className={`flex items-center gap-[${z.s(10)}px] rounded-[${z.s(16)}px] px-[${z.s(12)}px] py-[${z.s(8)}px] ${t.card}`}>
      <Icon name={kindOf(act.type)} size={z.s(22)} />
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${z.s(15)}px] font-bold truncate`}>{act.name || 'Activity'}</span>
        <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{ActLine({ v, act })}</span>
      </div>
    </div>
  )
}

function Activities({ v, whole }: { v: View; whole?: boolean }) {
  const { t, z } = v
  return (
    <div className={`${whole ? '' : 'flex-1 min-h-0 '}flex flex-col rounded-[${z.s(16)}px] px-[${z.s(12)}px] pt-[${z.s(10)}px] ${t.card}`}>
      <Label v={v} icon="run" color={t.ink} text="Recent activities" />
      {v.acts.length ? (
        <div className={whole ? '' : 'flex-1 min-h-0 overflow-y-auto'}>
          <div className="flex flex-col">
            {v.acts.map((act) => (
              <div className={`flex items-center gap-[${z.s(10)}px] py-[${z.s(7)}px] ${t.line}`}>
                <Icon name={kindOf(act.type)} size={z.s(20)} />
                <div className="flex-1 min-w-0 flex flex-col">
                  <span className={`text-[${z.s(15)}px] font-bold truncate`}>{act.name || 'Activity'}</span>
                  <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{ActLine({ v, act })}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <span className={`py-[${z.s(12)}px] text-[${z.s(14)}px] ${t.muted}`}>No activities recorded yet.</span>
      )}
    </div>
  )
}

function card(v: View, children: any, extra = '') {
  const { t, z } = v
  return <div className={`flex gap-[${z.s(14)}px] rounded-[${z.s(16)}px] p-[${z.s(12)}px] ${t.card} ${extra}`}>{children}</div>
}

// ---------------------------------------------------------------- the layouts

// A wide panel: Body Battery and the week on the left, four tiles and a row of
// the week's minutes, resting heart rate and the last activity on the right.
function wide(v: View) {
  const { t, z, W, H } = v
  const P = z.s(16), G = z.s(12)
  const inner = W - 2 * P
  const leftW = Math.round((inner - G) * 0.36)
  const tileW = Math.round((inner - G - leftW - G) / 2) - 2 * z.s(12)
  const bottom = z.s(108)
  const main = H - 2 * P - z.s(40) - 2 * G - bottom - (v.problem ? z.s(46) + G : 0)
  const chart = main - 2 * z.s(14) - z.s(18) - z.s(54) - z.s(16) - z.s(15) - 4 * z.s(8)
  return (
    <div className={`flex flex-col w-full h-full gap-[${G}px] p-[${P}px] ${t.page}`}>
      <Header v={v} />
      {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
      <div className={`flex-1 min-h-0 flex gap-[${G}px]`}>
        <div className={`w-[${leftW}px] shrink-0 flex flex-col gap-[${G}px]`}>
          <BatteryCard v={v} width={leftW} chart={chart} grow />
          <div className={`h-[${bottom}px] shrink-0 rounded-[${z.s(16)}px] p-[${z.s(12)}px] ${t.card}`}>
            <WeekSteps v={v} height={bottom - 2 * z.s(12) - z.s(18) - z.s(15) - 2 * z.s(4)} />
          </div>
        </div>
        <div className={`flex-1 min-w-0 flex flex-col gap-[${G}px]`}>
          <div className={`flex-1 min-h-0 flex gap-[${G}px]`}>
            <StepsTile v={v} />
            <SleepTile v={v} />
          </div>
          <div className={`flex-1 min-h-0 flex gap-[${G}px]`}>
            <HrvTile v={v} width={tileW} />
            <StressTile v={v} />
          </div>
          {card(v, [<Minutes v={v} />, <Resting v={v} />, <LastActivity v={v} />], `h-[${bottom}px] shrink-0 items-center`)}
        </div>
      </div>
    </div>
  )
}

// A landscape panel too short for the rows under the tiles (a 4.2" e-paper,
// a 2.8" LCD on its side): Body Battery and the four tiles.
function short(v: View) {
  const { t, z, W, H } = v
  const P = z.s(10), G = z.s(8)
  const inner = W - 2 * P
  const leftW = Math.round((inner - G) * 0.38)
  const tileW = Math.round((inner - G - leftW - G) / 2) - 2 * z.s(12)
  const chart = H - 2 * P - z.s(32) - G - 2 * z.s(14) - z.s(18) - z.s(54) - z.s(16) - z.s(15) - 4 * z.s(8) - (v.problem ? z.s(46) + G : 0)
  return (
    <div className={`flex flex-col w-full h-full gap-[${G}px] p-[${P}px] ${t.page}`}>
      <Header v={v} compact />
      {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
      <div className={`flex-1 min-h-0 flex gap-[${G}px]`}>
        <div className={`w-[${leftW}px] shrink-0 flex flex-col`}>
          <BatteryCard v={v} width={leftW} chart={chart} grow />
        </div>
        <div className={`flex-1 min-w-0 flex flex-col gap-[${G}px]`}>
          <div className={`flex-1 min-h-0 flex gap-[${G}px]`}>
            <StepsTile v={v} />
            <SleepTile v={v} />
          </div>
          <div className={`flex-1 min-h-0 flex gap-[${G}px]`}>
            <HrvTile v={v} width={tileW} />
            <StressTile v={v} />
          </div>
        </div>
      </div>
    </div>
  )
}

// A tall panel: everything stacked. A small one (a 2.8" LCD upright, a 4"
// square) scrolls under its header, a finger or the frame's keys away.
function tall(v: View) {
  const { t, z, W, H } = v
  const small = z.small || H < z.s(700)
  const roomy = H >= z.s(1000)
  const P = z.s(small ? 10 : roomy ? 16 : 12), G = z.s(small ? 8 : roomy ? 12 : 10)
  const cardW = W - 2 * P
  const tileW = Math.round((cardW - G) / 2) - 2 * z.s(12)
  const tileH = z.s(roomy || small ? 132 : 118)
  const tiles = (
    <div className={`flex flex-col gap-[${G}px]`}>
      <div className={`h-[${tileH}px] flex gap-[${G}px]`}>
        <StepsTile v={v} />
        <SleepTile v={v} />
      </div>
      <div className={`h-[${tileH}px] flex gap-[${G}px]`}>
        <HrvTile v={v} width={tileW} />
        <StressTile v={v} />
      </div>
    </div>
  )
  const week = (
    <div className={`rounded-[${z.s(16)}px] p-[${z.s(12)}px] ${t.card}`}>
      <WeekSteps v={v} height={z.s(roomy || small ? 56 : 40)} />
    </div>
  )
  const row = card(v, [<Minutes v={v} />, <Resting v={v} />])
  if (small)
    return (
      <div className={`flex flex-col w-full h-full gap-[${G}px] p-[${P}px] ${t.page}`}>
        <Header v={v} compact={z.small} />
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className={`flex flex-col gap-[${G}px]`}>
            {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
            <BatteryCard v={v} width={cardW} chart={z.s(84)} />
            {tiles}
            {week}
            {row}
            <Activities v={v} whole />
          </div>
        </div>
      </div>
    )
  return (
    <div className={`flex flex-col w-full h-full gap-[${G}px] p-[${P}px] ${t.page}`}>
      <Header v={v} />
      {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
      {roomy ? <BatteryCard v={v} width={cardW} chart={Math.round(H * 0.13)} /> : <BatteryCard v={v} width={cardW} chart={z.s(104)} side />}
      {tiles}
      {week}
      {row}
      {roomy ? <Activities v={v} /> : <LastRow v={v} />}
    </div>
  )
}

// A round panel, a watch face: Body Battery as a ring along the rim and large
// in the middle, steps, sleep and stress under it, HRV and resting heart rate
// in the arc at the bottom.
function round(v: View) {
  const { t, z, W, H, day, night, hrv, battery } = v
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, (R - 16) ** 2 - dy * dy)))
  const rr = R - 9
  const share = clamp(battery / 100, 0, 1)
  const a = share * 2 * Math.PI
  const arc = share >= 1
    ? `M ${cx} ${cy - rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy + rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy - rr}`
    : `M ${cx} ${cy - rr} A ${rr} ${rr} 0 ${share > 0.5 ? 1 : 0} 1 ${(cx + rr * Math.sin(a)).toFixed(1)} ${(cy - rr * Math.cos(a)).toFixed(1)}`
  const at = (dy: number, h: number, inner: any, extra = '') => {
    const w = chord(Math.abs(dy) > Math.abs(dy + h) ? dy : dy + h)
    return <div className={`absolute left-[${Math.round(cx - w / 2)}px] top-[${Math.round(cy + dy)}px] w-[${w}px] h-[${h}px] flex justify-center items-center ${extra}`}>{inner}</div>
  }
  const top = Math.round(R * 0.62)
  const stat = (icon: string, color: string, value: string, label: string) => (
    <div className="flex-1 min-w-0 flex flex-col items-center">
      <Icon name={icon} size={z.s(20)} color={color} />
      <span className={`text-[${z.s(22)}px] font-bold leading-tight`}>{value}</span>
      <span className={`text-[${z.s(12)}px] ${t.muted}`}>{label}</span>
    </div>
  )
  const lastNight = hrv && hrv.date === v.today && hrv.night ? hrv.night : 0
  const bottom = [
    lastNight ? `HRV ${lastNight} ms, ${(HRV_WORDS[hrv!.status] || '').toLowerCase()}` : hrv && hrv.week ? `HRV ${hrv.week} ms a night this week` : '',
    day.rhr ? `Resting ${day.rhr} bpm` : '',
  ].filter(Boolean)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <svg className={`absolute left-0 top-0 w-[${W}px] h-[${H}px]`} viewBox={`0 0 ${W} ${H}`} fill="none" strokeWidth={12} strokeLinecap="round">
        <circle cx={cx} cy={cy} r={rr} stroke={t.high ? '#ffffff' : t.bbSoft} />
        {t.high ? <circle cx={cx} cy={cy} r={rr} stroke="#000000" strokeWidth={2} /> : null}
        {share > 0 ? <path d={arc} stroke={t.bb} /> : null}
      </svg>
      {at(-top, z.s(22), (
        <div className={`flex items-center gap-[${z.s(6)}px] text-[${z.s(15)}px] ${t.muted}`}>
          <Icon name="bolt" size={z.s(17)} color={t.bb} />
          <span>Body Battery</span>
        </div>
      ))}
      {at(-top + z.s(26), z.s(70), <span className={`text-[${z.s(68)}px] font-bold leading-none`}>{battery ? String(battery) : '-'}</span>)}
      {at(-top + z.s(98), z.s(20), (
        <span className={`text-[${z.s(15)}px] font-bold text-[${t.bb}]`}>{battery ? batteryWord(battery) : v.synced ? '' : 'Not synced yet today'}</span>
      ))}
      {v.problem
        ? at(Math.round(R * 0.08), z.s(80), <Banner t={t} z={z} text={v.problem} />, 'px-[8px]')
        : at(Math.round(R * 0.06), z.s(68), (
            <div className={`flex w-full gap-[${z.s(4)}px]`}>
              {stat('steps', t.steps, grouped(day.steps), 'steps')}
              {stat('moon', t.sleep, night ? (night.score ? String(night.score) : hours(night.secs)) : '-', night && night.score ? 'sleep' : 'sleep')}
              {stat('gauge', t.medium, day.stress ? String(day.stress) : '-', 'stress')}
            </div>
          ))}
      {bottom.length ? at(Math.round(R * 0.48), z.s(20), <span className={`text-[${z.s(13)}px] truncate`}>{bottom[0]}</span>) : null}
      {bottom.length > 1 ? at(Math.round(R * 0.48) + z.s(20), z.s(20), <span className={`text-[${z.s(13)}px] ${t.muted} truncate`}>{bottom[1]}</span>) : null}
    </div>
  )
}

// ---------------------------------------------------------------- the screens before the dashboard

type Fit = { tight?: boolean; round?: { W: number; H: number } }

function keyScreen(t: Theme, z: Sizes, fit: Fit, s: Settings, problem: string) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="watch" title="Connect Garmin" problem={problem}
      intro="It reads your day with a key you make on Garmin Connect, once."
      steps={[
        {
          head: 'Open the Personal API key page',
          text: 'On Garmin Connect under Settings, or with the button:',
          code: keyPageOf(s).replace('https://', ''),
        },
        {
          head: 'Create a key and copy it',
          text: 'Accept the terms and pick how long it lasts, a year at most. Garmin shows it once.',
        },
        {
          head: 'Paste it into this scene',
          text: 'Into its Personal API key setting, and save.',
        },
      ]}
      note="Garmin emails you a week before the key runs out: make a new one then and paste it here."
      action={<BigButton t={t} z={z} icon="link" label="Open Garmin Connect" href={keyPageOf(s)} />} />
  )
}

function troubleScreen(t: Theme, z: Sizes, fit: Fit, problem: string) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="alert" title="No health data yet" problem={problem}
      intro="" steps={[{ head: 'The frame tries again', text: 'On its own in a minute or two, or now with Try again.' }]}
      action={<BigButton t={t} z={z} icon="refresh" label="Try again" onClick={readAgain} />} />
  )
}

// ---------------------------------------------------------------- the scene

export function get(app, context) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const isRound = context?.round === true
  const t = themeOf(app)
  const now = Date.now()
  const base = sizesOf(W, H)
  // A big upright panel (a 13.3" e-paper) fits the whole stacked page: about
  // 1,000 px of it at the scale of 1.
  const z = !isRound && H > W && base.k > 1 ? sizesOf(W, H, Math.max(1, Math.min(base.k, Math.floor((H / 1000) * 4) / 4))) : base
  // A tall panel sets the setup screens a little larger: its height has the room.
  const zSetup = !isRound && H >= W * 1.25 && base.k === 1 ? sizesOf(W, H, Math.min(1.3, W / 400, H / 640)) : base
  const fit: Fit = isRound ? { round: { W, H } } : { tight: H < 400 }
  const interval = Math.max(300, Number(app.state.refreshInterval) || 1800)

  newRender()
  const s = settingsOf(app)
  // Nothing changes on this screen until the settings do (a save renders).
  if (!s.key) {
    frameos.setNextSleep(3600)
    return keyScreen(t, zSetup, fit, s, '')
  }
  const sign = signOf(s)

  // The last good read, unless it was for another key.
  let cache = readCache(app)
  if (cache && cache.sign !== sign) cache = null
  let problem = ''

  // Read when it is due (the scene's interval) or asked for, and not while
  // Garmin asks the frame to wait. A failure keeps the last good read.
  const force = !!frameos.recall('force')
  if (force) frameos.remember('force', null)
  const due = !cache || now - cache.at >= interval * 1000 - 30000 || force
  let failed = false
  if (due && waitUntil() <= now) {
    const auth = readAuth(app)
    const current = session(app, s, force && !!auth.error && auth.sign === sign)
    if (current.keyBad) {
      frameos.setNextSleep(3600)
      return keyScreen(t, zSetup, fit, s, current.problem)
    }
    if (current.token) {
      const read = refresh({ app, s, token: current.token }, cache, now)
      if (read.keyBad) {
        frameos.setNextSleep(3600)
        return keyScreen(t, zSetup, fit, s, read.problem)
      }
      if (read.cache && read.cache !== cache) {
        read.cache.sign = sign
        cache = read.cache
        frameos.setState('cache', cache as any)
      }
      problem = read.problem
    } else {
      problem = current.problem
    }
    failed = !!problem
    frameos.remember('problem', problem)
    frameos.remember('fails', failed ? Number(frameos.recall('fails') || 0) + 1 : 0)
  } else {
    const auth = readAuth(app)
    if (auth.error && !auth.token && auth.sign === sign) {
      frameos.setNextSleep(3600)
      return keyScreen(t, zSetup, fit, s, auth.error)
    }
    problem = String(frameos.recall('problem') || '')
    if (!problem && due && waitUntil() > now) problem = slowDown(waitUntil(), now)
    failed = !!problem
  }

  // When to look again: the scene's interval, sooner after a failure (one,
  // two, four, eight, sixteen minutes), and not before Garmin's wait is over.
  const wait = waitUntil()
  if (wait > now) frameos.setNextSleep(Math.min(interval, Math.max(60, (wait - now) / 1000 + 1)))
  else if (failed) frameos.setNextSleep(Math.min(interval, 60 * 2 ** Math.min(4, Math.max(0, Number(frameos.recall('fails') || 1) - 1))))

  if (!cache) return troubleScreen(t, z, fit, problem || 'Reading your day from Garmin Connect...')

  const today = dayOf(now)
  const known = cache.days.find((day) => day.date === today)
  const days: Day[] = []
  for (let i = 6; i >= 0; i--) {
    const date = addDays(today, -i)
    days.push(cache.days.find((day) => day.date === date) || BLANK(date))
  }
  const day = known || BLANK(today)
  const lastPoint = cache.curve.length ? cache.curve[cache.curve.length - 1] : null
  const nights = cache.nights.filter((night) => night.secs > 0 && night.date <= today)
  const hrvs = cache.hrv.filter((h) => (h.night || h.week) && h.date <= today)
  const resting = days.filter((d) => d.rhr > 0)
  const v: View = {
    t, z, W, H, now, cache, problem, today, day, days,
    units: cache.units || 'metric',
    synced: !!known && (known.steps > 0 || known.bb > 0 || known.until !== ''),
    night: nights.length ? nights[nights.length - 1] : null,
    hrv: hrvs.length ? hrvs[hrvs.length - 1] : null,
    hrvNone: !!cache.hrvNone,
    battery: day.bb || (lastPoint && now / 60000 - lastPoint[0] < 6 * 60 ? lastPoint[1] : 0),
    im: weekMinutes(cache.days, today, cache.weekStart || 'monday'),
    rhrWeek: resting.length ? Math.round(resting.reduce((sum, d) => sum + d.rhr, 0) / resting.length) : 0,
    acts: cache.acts.slice(0, 5),
  }
  if (isRound) return round(v)
  if (W >= H * 1.3 && W >= 640 && H >= 380) return wide(v)
  if (W > H) return short(v)
  return tall(v)
}

