const FILLED: Record<string, boolean> = { watch: true, bolt: true, steps: true, moon: true, heart: true, flame: true, run: true, ride: true, swim: true, walk: true }

export const Icon = ({ name, size, width, color }: { name: string; size: number; width?: number; color?: string }) => {
  const filled = FILLED[name]
  const paint = color || 'currentColor'
  return (
    <svg className={`w-[${size}px] h-[${size}px] shrink-0`} viewBox="0 0 24 24"
      fill={filled ? paint : 'none'} stroke={paint} strokeWidth={filled ? 0 : width || 2}
      strokeLinecap="round" strokeLinejoin="round">
      <path d={PATHS[name] || PATHS.pulse} />
    </svg>
  )
}

