export function Banner({ t, z, text }: { t: Theme; z: Sizes; text: string }) {
  return (
    <div className={`flex items-center shrink-0 gap-[${z.s(10)}px] rounded-[${z.s(12)}px] px-[${z.s(12)}px] py-[${z.s(8)}px] ${t.banner}`}>
      <Icon name="alert" size={z.s(20)} />
      <span className={`flex-1 text-[${z.s(14)}px] line-clamp-3`}>{text}</span>
    </div>
  )
}

// A screen that says what to do, step by step, with a button at the bottom.
// `tight`: a short screen (a 4.2" e-paper, a 2.8" LCD), where the header,
// the steps and the note scroll as one column; a short and wide one (a 5.79"
// strip) puts the steps side by side. `round`: a round panel's whole canvas,
// where the title sits in the arc at the top, the steps scroll in the middle
// of the circle with the note after them, and the button stays in the arc at
// the bottom.
export type Step = { head: string; text: string; code?: string }
export function SetupScreen({ t, z, icon, title, intro, steps, problem, action, note, tight, round }: {
  t: Theme; z: Sizes; icon: string; title: string; intro: string; steps: Step[]; problem?: string; action?: any; note?: string
  tight?: boolean; round?: { W: number; H: number }
}) {
  const g = (px: number) => z.s(tight ? px * 0.55 : px)
  const side = !!tight && !round && z.W >= z.H * 2.4
  const f = (px: number, least: number) => Math.max(Math.round(least * (side ? 1.2 : 1)), z.s(px))
  const list = (
    <div className={`flex ${side ? 'flex-row' : 'flex-col'} gap-[${g(10)}px]`}>
      {steps.map((step, index) => (
        <div className={`flex ${side ? 'flex-1 min-w-0' : ''} gap-[${z.s(12)}px] rounded-[${z.s(14)}px] px-[${z.s(12)}px] py-[${g(10)}px] ${t.card}`}>
          <div className={`w-[${f(30, 20)}px] h-[${f(30, 20)}px] shrink-0 rounded-full flex items-center justify-center text-[${f(16, 12)}px] font-bold ${t.step}`}>
            {index + 1}
          </div>
          <div className={`flex-1 min-w-0 flex flex-col gap-[${tight ? 1 : 4}px]`}>
            <span className={`text-[${f(17, 12)}px] font-bold`}>{step.head}</span>
            <span className={`text-[${f(14, 10)}px] ${t.muted}`}>{step.text}</span>
            {step.code ? (
              <span className={`self-start rounded-[8px] px-[${z.s(8)}px] ${tight ? '' : 'py-[2px] '}font-mono text-[${f(13, 10)}px] ${t.code}`}>{step.code}</span>
            ) : null}
          </div>
        </div>
      ))}
    </div>
  )
  if (round) {
    const { W, H } = round
    const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
    const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
    const iconTop = Math.round(R * 0.93)
    const iconSize = z.s(38)
    const titleTop = iconTop - iconSize - z.s(4)
    const titleH = Math.round(z.s(22) * 1.3)
    const boxTop = titleTop - titleH - z.s(8)
    const actionH = action ? z.s(52) : 0
    const boxBottom = action ? Math.round(R * 0.38) : Math.round(R * 0.7)
    const boxW = Math.min(chord(boxTop), chord(boxBottom))
    const titleW = chord(titleTop)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${Math.round(cx - iconSize / 2)}px] top-[${Math.round(cy - iconTop)}px] w-[${iconSize}px] h-[${iconSize}px] rounded-full flex items-center justify-center ${t.step}`}>
          <Icon name={icon} size={z.s(21)} />
        </div>
        <div className={`absolute left-[${Math.round(cx - titleW / 2)}px] top-[${Math.round(cy - titleTop)}px] w-[${titleW}px] flex justify-center`}>
          <span className={`text-[${z.s(22)}px] font-bold leading-tight truncate`}>{title}</span>
        </div>
        <div className={`absolute left-[${Math.round(cx - boxW / 2)}px] top-[${Math.round(cy - boxTop)}px] w-[${boxW}px] h-[${boxTop + boxBottom}px] overflow-y-auto`}>
          <div className={`flex flex-col gap-[${z.s(10)}px]`}>
            {problem ? <Banner t={t} z={z} text={problem} /> : <span className={`text-[${z.s(15)}px] text-center ${t.muted}`}>{intro}</span>}
            {list}
            {note ? <span className={`text-[${z.s(13)}px] text-center ${t.muted}`}>{note}</span> : null}
          </div>
        </div>
        {action ? (
          <div className={`absolute left-[${Math.round(cx - chord(boxBottom + z.s(8) + actionH) / 2)}px] top-[${Math.round(cy + boxBottom + z.s(8))}px] w-[${chord(boxBottom + z.s(8) + actionH)}px] h-[${actionH}px] flex justify-center`}>
            {action}
          </div>
        ) : null}
      </div>
    )
  }
  const header = (
    <div className={`flex items-center gap-[${z.s(12)}px]`}>
      <div className={`w-[${f(48, 28)}px] h-[${f(48, 28)}px] shrink-0 rounded-full flex items-center justify-center ${t.step}`}>
        <Icon name={icon} size={f(26, 16)} />
      </div>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${f(26, 17)}px] font-bold leading-tight`}>{title}</span>
        {problem ? null : <span className={`text-[${f(15, 11)}px] ${t.muted}`}>{intro}</span>}
      </div>
    </div>
  )
  const noteLine = note ? <span className={`text-[${f(13, 10)}px] ${t.muted}`}>{note}</span> : null
  if (tight && !side)
    return (
      <div className={`flex flex-col w-full h-full gap-[${g(12)}px] p-[${g(20)}px] ${t.page}`}>
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className={`flex flex-col gap-[${g(12)}px]`}>
            {header}
            {problem ? <Banner t={t} z={z} text={problem} /> : null}
            {list}
            {noteLine}
          </div>
        </div>
        {action || null}
      </div>
    )
  return (
    <div className={`flex flex-col w-full h-full gap-[${g(12)}px] p-[${g(20)}px] ${t.page}`}>
      {header}
      {problem ? <Banner t={t} z={z} text={problem} /> : null}
      <div className="flex-1 min-h-0 overflow-y-auto">{list}</div>
      {action || null}
      {noteLine}
    </div>
  )
}

// The big button of a setup screen: a link (a QR code on the frame, a tab in
// the preview) or a tap.
export function BigButton({ t, z, icon, label, href, onClick }: {
  t: Theme; z: Sizes; icon: string; label: string; href?: string; onClick?: () => void
}) {
  const look = `self-center flex items-center gap-[${z.s(10)}px] h-[${z.s(52)}px] px-[${z.s(28)}px] rounded-full text-[${z.s(19)}px] font-bold ${t.primary}`
  const inside = [<Icon name={icon} size={z.s(22)} />, <span>{label}</span>]
  return href ? <a href={href} className={look}>{inside}</a> : <div className={look} onClick={onClick}>{inside}</div>
}
